'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const bootstrap=read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const runtime=read('docs/scifi-ui/scripts/formatx-reference-lock-v30.js');
const style=read('docs/scifi-ui/styles/formatx-reference-lock-v30.css');
const homepage=read('docs/scifi-ui/index.html');
const contract=JSON.parse(read('docs/scifi-ui/data/public-platform-contract.json'));

assert.match(bootstrap,/reference-lock-v30/,'production bootstrap must select v30');
assert.match(bootstrap,/formatx-reference-lock-v30\.js\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted renderer URL missing');
assert.match(bootstrap,/formatx-reference-lock-v30\.css\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted style URL missing');
assert.equal((bootstrap.match(/getContext\('webgl2'/g)||[]).length,0,'bootstrap must not create a duplicate WebGL2 context');
assert.equal((runtime.match(/getContext\('webgl2'/g)||[]).length,1,'production MAG must own exactly one WebGL2 context');
for(const token of ['gl.enable(gl.DEPTH_TEST)','gl.drawElements(gl.TRIANGLES','gl.drawElements(gl.LINES','function persp(','function crystal(','function torus(','function sphere(','uploaded-reference-20260810','glass-dominant-sparse-veins-r4','adaptive-60-plus-fps','IntersectionObserver','webglcontextlost']) assert.ok(runtime.includes(token),`missing production real3D contract: ${token}`);
assert.match(runtime,/p=\.68/,'concave four-tip p-norm silhouette missing');
assert.match(runtime,/mobile\?1\.50:1/,'mobile vertical reference calibration missing');
assert.match(runtime,/t=\.018/,'thin torus calibration missing');
assert.match(runtime,/for\(const k of\[2,4,6,8,10,R\]\)/,'sparse transverse vein geometry missing');
assert.match(runtime,/Math\.floor\(A\/12\)/,'sparse longitudinal vein geometry missing');
assert.match(runtime,/mesh\(shell,mul\(B,sc\(\.998,\.998,\.998\)\),1,\.30/,'dominant cyan glass surface pass missing');
assert.match(runtime,/mesh\(shell,mul\(B,sc\(\.992,\.992,\.992\)\),1,\.105/,'violet glass surface pass missing');
assert.match(runtime,/lines\(shell,B,\.22/,'reduced cyan vein opacity missing');
assert.match(runtime,/lines\(shell,mul\(B,rz\(\.0035\)\),\.055/,'reduced violet vein opacity missing');
assert.match(runtime,/fxCoreImageBacked='false'/,'non-image-backed marker missing');
assert.doesNotMatch(runtime,/drawImage\s*\(|new\s+Image\s*\(|createImageBitmap\s*\(|backgroundImage/i,'production MAG must not be raster-backed');
assert.doesNotMatch(runtime,/THREE\b|three\.js|babylon|playcanvas|model-viewer/i,'third-party scene engines are forbidden');
assert.doesNotMatch(runtime,/addEventListener\(['"](?:wheel|touchmove)['"][\s\S]{0,300}preventDefault/,'MAG must not capture scrolling');
assert.ok(homepage.includes('formatx-core-real3d-v20.js'),'homepage real3D bootstrap missing');
assert.match(style,/pointer-events:none/,'stage must not intercept input');
assert.match(style,/100dvh/,'dynamic viewport sizing missing');
assert.match(style,/--fx-core-x:50%/,'portrait reference centering missing');
assert.match(style,/40\.2%/,'reference core/horizon vertical alignment missing');
assert.match(style,/top:47\.5%/,'reference perspective floor start missing');
assert.match(style,/perspective\(560px\) rotateX\(63deg\)/,'reference floor perspective missing');
assert.match(style,/saturate\(1\.25\) contrast\(1\.16\) brightness\(2\.60\)/,'reference luminance calibration missing');
const q=contract.quality_contract;
assert.equal(q.mag_image_backed,false);assert.equal(q.mag_webgl_context_count,1);assert.equal(q.mag_paused_outside_hero,true);assert.equal(q.mag_reference_target,'four-tip-luminous-crystal-sci-fi-film-core');
console.log('PASS: reference MAG uses one indexed WebGL2 context, glass-dominant sparse veins, calibrated 40.2% horizon and reference luminance grade.');
